`,e.jsxs(t.p,{children:["Primary sources: ",e.jsx(t.a,{href:"https://github.com/dequelabs/axe-core",children:"Official documentation or repository"}),"; ",e.jsx(t.a,{href:"https://github.com/dequelabs/axe-core/blob/f49c1c49b5eafe1f8065e07c314f75968dd91333/doc/API.md",children:"API at inspected commit"})]}),`
